26	    $("#btnSearch").click(function () {
27	        if (!$("#frmFeesDueAsOnDateReport").valid()) {
28	            return false;
29	        }
30	        var strAsOnDate = $("#strAsOnDate").val();
31	        var varSchoolID = $("#SchoolID").val();
32	        var varSessionID = $("#SessionID").val();
33	
34	        var varFeesCategoryID = $('#FeesCategoryID').data('kendoMultiSelect').value();
35	        var varFeesBookID = $("#FeesBookID").val();
36	        var varFromSessionPartID = $("#FromSessionPartID").val();
37	        var varToSessionPartID = $("#ToSessionPartID").val();
38	        var varonlyAlumni = $("input[name='OnlyAlumniStudents']:checked").val();
39	
40	        var varhideDefine = $('#HideDefineAmount').is(':checked');
41	        var varhideCollection = $('#HideCollectionAmount').is(':checked');
42	        var varhidePending = $('#HidePendingAmount').is(':checked');
43	        var varhideSructure = $('#HideStructureAmount').is(':checked');
44	
45	        var varHideZero = $('#HideZero').is(':checked');
46	
47	        showLoader();
48	        var group = "";
49	        $.ajax({
50	            url: "/FeesDueAsOnDateReport/GetFeesCollectionAsOnDateReport",
51	            type: "GET",
52	            data: {
53	                strAsOnDate: strAsOnDate,
54	                SchoolID: varSchoolID,
55	                SchoolSessionID: varSessionID,
56	                FeesCategoryID: varFeesCategoryID.join(','),
57	                FeesBookID: varFeesBookID == "" ? 0 : varFeesBookID,
58	                FromSessionPartID: varFromSessionPartID == "" ? -1 : varFromSessionPartID,
59	                ToSessionPartID: varToSessionPartID == "" ? -1 : varToSessionPartID,
60	                hideDefine: varhideDefine,
61	                hideCollection: varhideCollection,
62	                hidePending: varhidePending,
63	                hideSructure: varhideSructure,
64	                hideZero: varHideZero,
65	                OnlyAlumni: varonlyAlumni,
66	            },
67	            dataType: "json",
68	            success: function (response) {
69	                group = response.groupedFields;
70	                hideLoader();
71	                kendoexportfields = [];
72	                if ($("#strAsOnDate").val() != "") {
73	                    kendoexportfields.push("As On Date : " + $("#strAsOnDate").val());
74	                }
75	                if ($("#FeesBookID option:selected").val() != "") {
76	                    kendoexportfields.push(" | Fees Book : " + $("#FeesBookID option:selected").text());
77	                }
78	                if ($("#FromSessionPartID option:selected").val() || $("#ToSessionPartID option:selected").val()) {
79	                    kendoexportfields.push(" | Session Part : " + $("#FromSessionPartID option:selected").text() + " - " + $("#ToSessionPartID option:selected").text());
80	                }
81	                const $grid = $("#KFeesCollectionFeesDueAsOnDateReport").empty();
82	                if (response.data.length > 0) {
83	                    var aggregates = response.aggregateFields.map(function (field) {
84	                        return { field: field, aggregate: "sum" };
85	                    });
86	                    $grid.kendoGrid({
87	                        dataSource: {
88	                            data: response.data,
89	                            aggregate: aggregates,
90	                            group: group
91	                        },
92	                        columns: response.columns,
93	                        pageable: {
94	                            pageSizes: [10, 20, 50, 100, 500],
95	                            buttonCount: 5,
96	                            refresh: true,
97	                            pageSize: 100,
98	                        },
99	                        resizable: true,
100	                        groupable: true,
101	                        selectable: "single",
102	                        filterable: {
103	                            extra: false,
104	                            operators: {
105	                                string: {
106	                                    clear: "Clear",
107	                                    eq: "Is equal to",
108	                                    contains: "Contains"
109	                                }
110	                            }
111	                        },
112	                        //columnMenu: true,
113	                        toolbar: ["excel"],
114	                        excel: {
115	                            fileName: "FeesDueAsOnDateReport.xlsx",
116	                            filterable: true,
117	                            allPages: true,
118	                            proxyURL: "/Grid/Excel_Export_Save"
119	                        },
120	                        excelExport: ExcelExport,
121	                        sortable: true,
122	                        navigatable: true,
123	                        dataBound: function () {
124	                            var gridHeight = $(".k-grid-content").outerHeight();
125	                            if (gridHeight < 400) {
126	                                $(".k-grid-content").css("height", "400px");
127	                            }
128	                        }
129	                    });
130	                    //const grid = $grid.data("kendoGrid");
131	                    //grid.dataSource.group(group);
132	                    KendoGridHeightWithoutButton("KFeesCollectionFeesDueAsOnDateReport");
133	                }
134	                else {
135	                    toastr.error("No data Found");
136	                }
137	                hideLoader();
138	            },
139	            error: function (xhr, status, error) {
140	                console.error("Error fetching data: " + error);
141	                hideLoader();
142	            }
143	        });
144	    });
145	});
146	function CommonPost(url, data, dropDownId) {
147	    $(`#${dropDownId}`).fillSelect([]);
148	    $(".box").showLoader();
149	    $.post(url, data)
150	        .done(function (res) {
151	            $(`#${dropDownId}`).fillSelect(res);
152	        })
153	        .always(function () {
154	            $(".box div.overlay").hideLoader();
155	        })
156	}
157	function FillSchoolSessionList() {
158	    if ($("#SchoolID").val() == "" || $("#SchoolID").val() == "0") {
159	        return;
160	    }
161	    CommonPost('/FeesDueAsOnDateReport/FillSchoolSessionList', { p_SchoolID: $("#SchoolID").val() }, "SessionID");
162	}
