197	    if ($("#SchoolID").val() == "") {
198	        return;
199	    }
200	    //var varFeesCategoryID = $('select[name="FeesCategoryIDSelectList"]').val();
201	    //if (varFeesCategoryID == "" || varFeesCategoryID == null || (Array.isArray(varFeesCategoryID) && varFeesCategoryID.length === 0)) {
