206	function FillAllSessionPartListOfSchoolSession() {
207	    $("#FromSessionPartID").fillSelect([]);
208	    $("#ToSessionPartID").fillSelect([]);
209	    if ($("#SchoolID").val() == "" || $("#SchoolSessionID").val() == "") {
210	        return;
211	    }
212	    $(".box").showLoader();
213	    $.post('/FeesDueAsOnDateReport/FillAllSessionPartListOfSchoolSession', { p_SchoolID: $("#SchoolID").val(), p_SchoolSessionID: $("#SessionID").val() })
214	        .done(function (res) {
215	            res.unshift({ Texts: 'Admission', Value: '0' })
216	            $("#FromSessionPartID").fillSelect(res);
217	            $("#ToSessionPartID").fillSelect(res);
218	        })
219	        .always(function () {
220	            $(".box div.overlay").hideLoader();
221	        })
222	}

