51	        {
52	            model.SchoolStandardIDSelectList = new SelectList(new CommonRepository().FillStandardBySchoolId(new CurrentSession().LoginSchoolID), "Value", "Texts", model.SchoolStandardID);
53	            model.StandardDivisionIDSelectList = new SelectList(new CommonRepository().FillStandardDivisionBySchoolStandardID(model.SchoolStandardID), "Value", "Texts");
54	            model.TermIDSelectList = new SelectList(new EnumRepository().GetFilterEnumDatas(new EnumModel() { EnumTypeID = (int)EnumEnumType.Term }), "EnumID", "EnumValue", model.TermID);
55	
56	            return model;
57	        }
58	        #endregion
