61	        public JsonResult CheckConsolidateDataExists(int SchoolStandardID, int StandardDivisionID, int TermID)
62	        {
63	            ConsolidateResultModel crmodel = new ConsolidateResultModel();
64	            crmodel.SchoolID = new CurrentSession().LoginSchoolID;
65	            crmodel.SchoolSessionID = new CurrentSession().SchoolSessionID;
66	            crmodel.SchoolStandardID = SchoolStandardID;
67	            crmodel.StandardDivisionID = StandardDivisionID;
68	            crmodel.TermID = TermID;
69	
70	            var DataExists = new ConsolidateResultRepository().CheckDataExist(crmodel);
71	            return Json(DataExists.Count > 0, JsonRequestBehavior.AllowGet);
72	        }
73	        public PartialViewResult GetStudentList(int SchoolStandardID, int StandardDivisionID, int TermID)
74	        {
75	            try
76	            {
77	                ConsolidateResultModel model = new ConsolidateResultModel();
78	                if (SchoolStandardID != 0 && StandardDivisionID != 0 && TermID != 0)
79	                {
80	                    ConsolidateResultModel param = new ConsolidateResultModel();
81	                    param.SchoolID = new CurrentSession().LoginSchoolID;
82	                    param.SchoolSessionID = new CurrentSession().SchoolSessionID;
83	                    param.SchoolStandardID = SchoolStandardID;
84	                    param.StandardDivisionID = StandardDivisionID;
