    public class ConsolidateResultReportController : BaseController
    {
        #region Global Variable Declaration
        IRepository<Cceconfiguration> _CCE;
        IRankProfile _RankProfile;
        ConsolidateResultRepository objConsolidateResultRepository = new ConsolidateResultRepository();
        ResultGradeRepository objResultGradeRepository = new ResultGradeRepository();

        public ConsolidateResultReportController(IRepository<Cceconfiguration> cce, IRankProfile rankProfile)
        {
            _CCE = cce;
            _RankProfile = rankProfile;
        }
