        // GET: ConsolidateResultReport
        public ActionResult Index()
        {
            ConsolidateResultReportModel model = new ConsolidateResultReportModel();
            model = BindDropdown(model);
            if (string.IsNullOrEmpty(model.SchoolReopenDate))
            {
                model.SchoolReopenDate = DateTimes.Now().ToString("dd/MM/yyyy");
            }
            if (string.IsNullOrEmpty(model.ResultDate))
            {
                model.ResultDate = DateTimes.Now().ToString("dd/MM/yyyy");
            }
            return View(model);
        }

        #region Bind Dropdown Datas
        public ConsolidateResultReportModel BindDropdown(ConsolidateResultReportModel model)
        {
            model.SchoolStandardIDSelectList = new SelectList(new CommonRepository().FillStandardBySchoolId(new CurrentSession().LoginSchoolID), "Value", "Texts", model.SchoolStandardID);
            model.StandardDivisionIDSelectList = new SelectList(new CommonRepository().FillStandardDivisionBySchoolStandardID(model.SchoolStandardID), "Value", "Texts");
            model.TermIDSelectList = new SelectList(new EnumRepository().GetFilterEnumDatas(new EnumModel() { EnumTypeID = (int)EnumEnumType.Term }), "EnumID", "EnumValue", model.TermID);

            return model;
        }
        #endregion

        public JsonResult CheckConsolidateDataExists(int SchoolStandardID, int StandardDivisionID, int TermID)
        {
            ConsolidateResultModel crmodel = new ConsolidateResultModel();
            crmodel.SchoolID = new CurrentSession().LoginSchoolID;
            crmodel.SchoolSessionID = new CurrentSession().SchoolSessionID;
            crmodel.SchoolStandardID = SchoolStandardID;
            crmodel.StandardDivisionID = StandardDivisionID;
            crmodel.TermID = TermID;

            var DataExists = new ConsolidateResultRepository().CheckDataExist(crmodel);
            return Json(DataExists.Count > 0, JsonRequestBehavior.AllowGet);
        }

        #region Get Student List for Kendo Grid
        public JsonResult GetStudentList(int SchoolStandardID, int StandardDivisionID, int TermID, int OnlyAlumni = 1, string SchoolReopenDate = "", string ResultDate = "")
