                    {
                        model.ConsolidateResultList = objConsolidateResultRepository.GetStudentList(param);
                        model.FinalResult = (from Total in model.ConsolidateResultList
                                             group Total by Total.StudentCurrentID into TotalData
                                             select new FinalResultModel()
                                             {
                                                 StudentCurrentID = TotalData.Key,
                                                 OverallTotalBefore = TotalData.Where(x => x.IsIncludeInTotal == 1).Where(x => x.TotalBefore != -999).Sum(x => x.TotalBefore), /// -999 for absent
                                                 OverallTotalAfter = TotalData.Where(x => x.IsIncludeInTotal == 1).Where(x => x.ObtainedTotalMarks != -999).Sum(x => x.ObtainedTotalMarks),
                                                 SpecialTotal = TotalData.Sum(x => x.Special),
                                                 GraceTotal = TotalData.Sum(x => x.Grace),
                                                 CondTotal = TotalData.Sum(x => x.Cond),
                                                 Result = TotalData.Select(x => x.IsFailed).Any(a => a == 1) ? "Failed" : "Pass",
                                                 TotalofTotalMarks = TotalData.Sum(x => x.Totaltotalmarks),
                                                 Percentage = TotalData.Where(x => x.IsIncludeInTotal == 1).Sum(x => x.Totaltotalmarks) > 0
                                                     ? (TotalData.Where(x => x.IsIncludeInTotal == 1).Where(x => x.ObtainedTotalMarks != -999).Sum(x => x.TotalBefore) / TotalData.Where(x => x.IsIncludeInTotal == 1).Sum(x => x.Totaltotalmarks)) * 100
                                                     : 0,
                                                 RollNo = TotalData.FirstOrDefault().RollNo,
                                             }).ToList();

                        // --- For Give Rank
                        // Rule - when any student is used condonation marks then don't apply rank on that
                        var prdata = model.FinalResult.OrderByDescending(a => a.Percentage)
                            .Where(x => x.Result == "Pass")
                            .Select(x => new { x.Percentage, x.Rank }).Distinct().ToList();
                        int i = 1;
                        var rankData = (from pr in prdata select new FinalResultModel() { Percentage = pr.Percentage, Rank = i++ }).ToList();

                        CCEConfigurationModel cCEConfigurationModel = new CCEConfigurationRepository().GetFilterCCEConfigurationData(new CCEConfigurationModel() { SchoolID = param.SchoolID, SchoolSessionID = param.SchoolSessionID, SchoolStandardID = param.SchoolStandardID, TermID = param.TermID, ActiveStatus = 1 }).FirstOrDefault();

                        ResultGradeModel GradeID = objResultGradeRepository.GetFilterResultGradeDatas(new ResultGradeModel() { SchoolID = new CurrentSession().LoginSchoolID, ResultGradeID = (cCEConfigurationModel?.ResultGradeID ?? 0) }).FirstOrDefault();
                        var Grade = GradeID != null ? objResultGradeRepository.GetFilterResultGradePercentageDatas(new ResultGradePercentageModel() { ResultGradeID = GradeID.ResultGradeID }) : new List<ResultGradePercentageModel>();

                        model.FinalResult.Where(x => x.Result == "Pass").ToList().ForEach(x => x.Grade = Grade.Where(y => y.FromPercentage <= x.Percentage && y.ToPercentage >= x.Percentage).Select(y => y.GradeName).FirstOrDefault());
                        model.FinalResult.Where(x => x.Result == "Failed").ToList().ForEach(x => x.Grade = Grade.Where(y => y.FromPercentage <= x.Percentage && y.ToPercentage >= x.Percentage).Select(y => y.GradeName).FirstOrDefault());

                        // Rule : when used grace marks then `Promoted` and when use condonation marks then `Pass And Promoted`
                        model.FinalResult
                            .Where(w => w.Result != "Failed")
                            .GroupBy(g => g.StudentCurrentID)
                            .ToList()
                            .ForEach(f =>
                            {
                                f.ToList().ForEach(e => e.Result = f.Sum(s => s.GraceTotal) > 0 && f.Sum(s => s.CondTotal) == 0 ? "Pass" : f.Sum(s => s.CondTotal) > 0 ? "Promoted" : e.Result);
                            });

                        Cceconfiguration cce = _CCE.GetEntity().Where(w => w.SchoolId == param.SchoolID
                            && w.SchoolSessionId == param.SchoolSessionID
                            && w.SchoolStandardId == param.SchoolStandardID
                            && w.TermId == (param.TermID == 200 ? w.TermId : param.TermID)
                            && w.ActiveStatus == 1).OrderBy(o => o.TermId).LastOrDefault();

                        if (cce != null)
                        {
                            RankProfile RankProfile;
                            if (cce.RankProfileId.HasValue && cce.RankProfileId.Value > 0)
                            {
                                RankProfile = _RankProfile.GetDefaultRankProfile(cce.RankProfileId.Value);
                                TempData["RankProfile"] = RankProfile;

                                // Rule : when rank profile marked absent as fail then if a student not appear in any exam considered as fail 
                                model.FinalResult.OrderByDescending(a => a.Percentage)
                                    .Where(x => x.Result == "Pass" && model.ConsolidateResultList.Any(a => a.StudentCurrentID == x.StudentCurrentID && (RankProfile.AbsentAsFail && ((a.AbsentInAny > 0 && a.IsIncludeInTotal == 1) || (a.AbsentInAny > 0 && a.IsIncludeInTotal == 0 && RankProfile.ConsiderOptionalSubjectForResult)))))
                                    .ToList().ForEach(x => x.Result = "Failed");

                                // Rule : give rank only to pass student
                                model.FinalResult.OrderByDescending(a => a.Percentage)
                                    .Where(x => x.Result == "Pass").ToList().ForEach(x => x.Rank = rankData.Where(y => y.Percentage == x.Percentage).Select(y => y.Rank).FirstOrDefault());

                                List<ResultRankModel> StudentRank = new List<ResultRankModel>();
                                StudentRank = model.FinalResult.Select(s => new ResultRankModel() { id = s.StudentCurrentID, Fail = s.Result != "Pass", Percentage = Convert.ToDecimal(s.Percentage) }).ToList();
                                List<ResultRankModel> RankList = new CCEReportRepository().GetResultRank(RankProfile.Id == 0 ? null : (short?)RankProfile.Id, StudentRank);

                                model.FinalResult.ForEach(f =>
                                {
                                    int? rank = RankList.FirstOrDefault(d => d.id == f.StudentCurrentID)?.Rank;
                                    f.Rank = rank.HasValue ? rank.Value : 0;
                                });
                                model.FinalResult.ForEach(f =>
                                {
                                    f.Percentage = f.Result == "Failed" && RankProfile.HidePercentageWhenFail == true ? 0 : f.Percentage;
                                    f.Grade = f.Result == "Failed" && RankProfile.HideGradeWhenFail == true ? null : f.Grade;
                                });
                            }
                            else
                            {
                                var defaultProfile = _RankProfile.GetDefaultExamProfile(null, param.SchoolID, null).Result;
                                string hp, hg, hper;
                                int temp;
                                RankProfile = new RankProfile
                                {
                                    Id = 0,
                                    HidePercentageWhenFail = defaultProfile != null && defaultProfile.TryGetValue("HidePercentageWhenFail", out hp) &&
                                        int.TryParse(hp, out temp) && temp == 1,
                                    HideGradeWhenFail = defaultProfile != null && defaultProfile.TryGetValue("HideGradeWhenFail", out hg) &&
                                        int.TryParse(hg, out temp) && temp == 1,
                                    HidePercentileWhenFail = defaultProfile != null && defaultProfile.TryGetValue("HidePercentileWhenFail", out hper) &&
                                        int.TryParse(hper, out temp) && temp == 1
                                };

                                // Rule : give rank only to pass student
                                model.FinalResult.OrderByDescending(a => a.Percentage)
                                    .Where(x => x.Result == "Pass").ToList().ForEach(x => x.Rank = rankData.Where(y => y.Percentage == x.Percentage).Select(y => y.Rank).FirstOrDefault());

                                model.FinalResult.ForEach(f =>
                                {
                                    f.Percentage = f.Result == "Failed" && RankProfile.HidePercentageWhenFail == true ? 0 : f.Percentage;
                                    f.Grade = f.Result == "Failed" && RankProfile.HideGradeWhenFail == true ? null : f.Grade;
                                });
                            }
                        }
                    }
                }

                model.ConsolidateResultList = model.ConsolidateResultList.OrderBy(x => Convert.ToInt32(string.IsNullOrEmpty(x.RollNo) ? "0" : x.RollNo)).ThenBy(o => o.StudentCurrentID).ThenBy(o => o.DisplayOrder).ToList();
                model.FinalResult = model.FinalResult.OrderBy(x => Convert.ToInt32(string.IsNullOrEmpty(x.RollNo) ? "0" : x.RollNo)).ThenBy(o => o.StudentCurrentID).ToList();

                var dt = model.ConsolidateResultList;

                // Unique Subjects ordered by DisplayOrder
                var uniqueSubjects = dt
                    .Select(r => new
                    {
                        SubjectID = r.SubjectID,
                        SubjectExamTypeID = r.SubjectExamTypeID,
                        SubjectIDName = (r.SubjectIDName ?? "").Trim(),
                        DisplayOrder = r.DisplayOrder,
                        PassingMarks = r.PassingMarks,
                        Totaltotalmarks = r.Totaltotalmarks
                    })
                    .GroupBy(x => new { x.SubjectID, x.SubjectExamTypeID, x.SubjectIDName })
                    .Select(g => g.First())
                    .OrderBy(o => o.DisplayOrder).ThenBy(r => r.SubjectID)
                    .ToList();

                // Static Base Columns (Roll No, Student Name, GR No)
                var columns = new List<object>
                {
                    new { field = "RollNo", title = "Roll No", width = "90", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:center;", @class = "setcenter" }, headerAttributes = new { style = "text-align:center;", @class = "setcenter" } },
                    new { field = "StudentName", title = "Student Name", width = "220", filterable = new { multi = true, search = true }, footerTemplate = "<div style='text-align:right; font-weight:bold;'>Grand Total :</div>" },
                    new { field = "GrNo", title = "GR No", width = "100", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:center;", @class = "setcenter" }, headerAttributes = new { style = "text-align:center;", @class = "setcenter" } }
                };

                var aggregateFields = new List<string>();
                var groupedFields = new List<object>();

                // Build Dynamic Subject Columns: Subject Header -> [Passing/Total, Special, Grace, Cond, Final]
                foreach (var sub in uniqueSubjects)
                {
                    string keyPrefix = $"Sub_{sub.SubjectID}_{sub.SubjectExamTypeID}";

                    var subColumns = new List<object>
                    {
                        new { field = $"{keyPrefix}_Marks", title = $"{sub.PassingMarks}/{sub.Totaltotalmarks}", width = "100", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;", @class = "clsAmount" } },
                        new { field = $"{keyPrefix}_Special", title = "Special", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;", @class = "clsAmount" } },
                        new { field = $"{keyPrefix}_Grace", title = "Grace", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;", @class = "clsAmount" } },
                        new { field = $"{keyPrefix}_Cond", title = "Cond.", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;", @class = "clsAmount" } },
                        new { field = $"{keyPrefix}_Final", title = "Final", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;", @class = "clsAmount" } }
                    };

                    columns.Add(new
                    {
                        title = sub.SubjectIDName,
                        headerAttributes = new { style = "text-align:center;" },
                        columns = subColumns
                    });
                }

                // Final Result Column Group
                var finalResultCols = new List<object>
                {
                    new { field = "OverallTotalBefore", title = "Total", width = "90", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;" }, footerTemplate = "<div style='text-align:right; font-weight:bold;'>#= kendo.toString(sum, 'n2') #</div>" },
                    new { field = "SpecialTotal", title = "Special", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;" }, footerTemplate = "<div style='text-align:right; font-weight:bold;'>#= kendo.toString(sum, 'n2') #</div>" },
                    new { field = "GraceTotal", title = "Grace", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;" }, footerTemplate = "<div style='text-align:right; font-weight:bold;'>#= kendo.toString(sum, 'n2') #</div>" },
                    new { field = "CondTotal", title = "Cond.", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;" }, footerTemplate = "<div style='text-align:right; font-weight:bold;'>#= kendo.toString(sum, 'n2') #</div>" },
                    new { field = "OverallTotalAfter", title = "Final", width = "90", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;" }, footerTemplate = "<div style='text-align:right; font-weight:bold;'>#= kendo.toString(sum, 'n2') #</div>" },
                    new { field = "Percentage", title = "%", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:right;", @class = "clsAmount" }, headerAttributes = new { style = "text-align:center;" } },
                    new { field = "Grade", title = "Grade", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:center;" }, headerAttributes = new { style = "text-align:center;" } },
                    new { field = "Result", title = "Result", width = "90", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:center;" }, headerAttributes = new { style = "text-align:center;" } },
                    new { field = "Rank", title = "Rank", width = "80", filterable = new { multi = true, search = true }, attributes = new { style = "text-align:center;" }, headerAttributes = new { style = "text-align:center;" } }
                };

                columns.Add(new
                {
                    title = "Final Result",
                    headerAttributes = new { style = "text-align:center;" },
                    columns = finalResultCols
                });

                aggregateFields.Add("OverallTotalBefore");
                aggregateFields.Add("SpecialTotal");
                aggregateFields.Add("GraceTotal");
                aggregateFields.Add("CondTotal");
                aggregateFields.Add("OverallTotalAfter");

                // Build Student Data Rows (Dictionary per student)
                var groupedRows = dt
                    .GroupBy(r => new
                    {
                        r.StudentCurrentID,
                        RollNo = (r.RollNo ?? "").Trim(),
                        StudentCurrentIDName = (r.StudentCurrentIDName ?? "").Trim(),
                        GRNo = (r.GRNo ?? "").Trim()
                    })
                    .Select(g =>
                    {
                        var studentId = g.Key.StudentCurrentID;
                        var final = model.FinalResult.FirstOrDefault(f => f.StudentCurrentID == studentId);

                        var row = new Dictionary<string, object>
                        {
                            ["RollNo"] = g.Key.RollNo,
                            ["StudentName"] = g.Key.StudentCurrentIDName,
                            ["GrNo"] = g.Key.GRNo,
                            ["OverallTotalBefore"] = final != null ? (object)Math.Round(final.OverallTotalBefore, 2) : 0,
                            ["SpecialTotal"] = final != null ? (object)Math.Round(final.SpecialTotal, 2) : 0,
                            ["GraceTotal"] = final != null ? (object)Math.Round(final.GraceTotal, 2) : 0,
                            ["CondTotal"] = final != null ? (object)Math.Round(final.CondTotal, 2) : 0,
                            ["OverallTotalAfter"] = final != null ? (object)Math.Round(final.OverallTotalAfter, 2) : 0,
                            ["Percentage"] = final != null ? (object)Math.Round(final.Percentage, 2) : 0,
                            ["Grade"] = final?.Grade ?? "",
                            ["Result"] = final?.Result ?? "",
                            ["Rank"] = final != null && final.Rank > 0 ? (object)final.Rank : ""
                        };

                        // 1. Initialize all subject columns
                        foreach (var sub in uniqueSubjects)
                        {
                            string keyPrefix = $"Sub_{sub.SubjectID}_{sub.SubjectExamTypeID}";
                            row[$"{keyPrefix}_Marks"] = "-";
                            row[$"{keyPrefix}_Special"] = 0;
                            row[$"{keyPrefix}_Grace"] = 0;
                            row[$"{keyPrefix}_Cond"] = 0;
                            row[$"{keyPrefix}_Final"] = 0;
                        }

                        // 2. Populate student's marks for each subject
                        foreach (var item in g)
                        {
                            string keyPrefix = $"Sub_{item.SubjectID}_{item.SubjectExamTypeID}";
                            string strTotalBefore = item.TotalBefore == -999 ? "AB" : item.TotalBefore.ToString();
                            row[$"{keyPrefix}_Marks"] = strTotalBefore;
                            row[$"{keyPrefix}_Special"] = item.Special;
                            row[$"{keyPrefix}_Grace"] = item.Grace;
                            row[$"{keyPrefix}_Cond"] = item.Cond;
                            row[$"{keyPrefix}_Final"] = item.ObtainedTotalMarks == -999 ? (object)"AB" : item.ObtainedTotalMarks;
                        }

                        return row;
                    })
                    .OrderBy(o => Convert.ToInt32(string.IsNullOrEmpty(o["RollNo"]?.ToString()) ? "0" : o["RollNo"]?.ToString()))
                    .ToList();

                JsonResult jsonResult = Json(new { data = groupedRows, columns = columns, aggregateFields = aggregateFields, groupedFields = groupedFields }, JsonRequestBehavior.AllowGet);
                jsonResult.MaxJsonLength = int.MaxValue;
                return jsonResult;
            }
            catch (Exception _Exception)
            {
                new CommonHelper().SaveError(_Exception);
                throw _Exception;
            }
        }
        #endregion

        private static string Sanitize(string input)
        {
            if (string.IsNullOrEmpty(input)) return "";
            return Regex.Replace(input, @"[^a-zA-Z0-9]", "");
        }
    }
}
